class Solution { public int[][] insertInterval(int[][] intervals, int[] added) { java.util.ArrayList<int[]> r=new java.util.ArrayList<>();int i=0;while(i<intervals.length&&intervals[i][1]<added[0])r.add(intervals[i++]);while(i<intervals.length&&intervals[i][0]<=added[1]){added[0]=Math.min(added[0],intervals[i][0]);added[1]=Math.max(added[1],intervals[i][1]);i++;}r.add(added);while(i<intervals.length)r.add(intervals[i++]);return r.toArray(new int[0][]); } }
